(function(){
  let left=0,doneF=null;
  for(const k in IB.IMG_B64){
    const im=new Image();left++;
    im.onload=im.onerror=()=>{left--;if(left<=0&&doneF)doneF();};
    im.src=IB.IMG_B64[k];IB.IMG[k]=im;
  }
  IB.IMG_READY=new Promise(res=>{doneF=res;setTimeout(res,2500);});
})();
IB.img=(n)=>{const im=IB.IMG[n];if(!im)return null;if(im.tagName==='CANVAS')return im;return (im.complete&&im.naturalWidth>0)?im:null;};
IB._mir={};
IB.mirror=(n)=>{if(IB._mir[n])return IB._mir[n];const im=IB.img(n);if(!im)return null;
  const c=IB.mk(im.width,im.height);c.g.save();c.g.scale(-1,1);c.g.drawImage(im,-im.width,0);c.g.restore();
  IB._mir[n]=c;return c;};
/* v11.0 «ПРИЛИПЛИ ДО ДОРОГИ»: у спрайтів авто з-низу є ПРОЗОРИЙ відступ
   (17-18px у ізо-машин ч.1!) — саме через нього авто «літали» над асфальтом.
   IB.CARPAD[модель] = кількість прозорих рядків унизу спрайта; drawCar
   піднімає спрайт на pad*sc, щоб КОЛЕСА стояли на смузі. Значення обчислюються
   зі спрайтів після декодування; нижче — перевірені фолбеки. */
IB.CARPAD={vaz:18,lanos:17,suv:17,truck:17,};
IB.computeCarPads=()=>{
  for(const k in IB.IMG){
    if(k.indexOf('car_')!==0)continue;
    const im=IB.img(k);if(!im)continue;
    try{
      const c=IB.mk(im.width,im.height);
      c.g.drawImage(im,0,0);
      const d=c.g.getImageData(0,0,im.width,im.height).data;
      let pad=0;
      for(let yy=im.height-1;yy>=0;yy--){
        let any=false;
        for(let xx=0;xx<im.width;xx++){if(d[(yy*im.width+xx)*4+3]>12){any=true;break;}}
        if(any)break;pad++;
      }
      const model=k.slice(4).replace(/_(se|sw|ne|nw)$/,'').replace(/_d$/,'');
      if(pad>=0&&pad<im.height){
        IB.CARPAD[model]=pad;
        /* v18.7: варіанти кольорів (_a/_b/_c) — пад той самий для бази */
        const base=model.replace(/_([a-d])$/,'');
        if(base!==model)IB.CARPAD[base]=pad;
      }
    }catch(e){/* canvas заборонений — лишаємо фолбек */}
  }
};